def transform(grid):
    out = [row[:] for row in grid]
    # Recolor the background tail after the rightmost 8 in each row to 1.
    for r, row in enumerate(grid):
        positions = [c for c, value in enumerate(row) if value == 8]
        if positions:
            for c in range(positions[-1] + 1, len(row)):
                if row[c] != 8:
                    out[r][c] = 1
    return out
