{
 "path": "/home/ubuntu/continual-arc-baselines/.workbench/runs/adhoc-openclawlearner-1790687887/attempts/6363bae62cf74cadb6849e205726b671/system/state/workspace/programs/task-156a9b0a.py",
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    pts = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != bg]
    # Continue each diagonal line of at least two matching markers beyond its far endpoint.
    for r, c, color in pts:
        for rr, cc, other in pts:
            if other != color or (r, c) == (rr, cc):
                continue
            dr, dc = rr - r, cc - c
            if abs(dr) == abs(dc) and dr:
                step_r = 1 if dr > 0 else -1
                step_c = 1 if dc > 0 else -1
                x, y = rr + step_r, cc + step_c
                while 0 <= x < h and 0 <= y < w:
                    if out[x][y] == bg:
                        out[x][y] = color
                    x += step_r
                    y += step_c
    return out
